"""検査 i のうち、YAML の参照の向き。

YAML の参照 (属性の refers_to) は、参照する YAML のディレクトリの祖先のディレクトリにある YAML の定義を指さない。
同じディレクトリ・子孫のディレクトリ・別のサブツリー・ほかのドメインは指してよい。判定は参照先の定義を書いた場所で行う。
違反したときの直し方は、参照される定義をサブディレクトリの YAML に移すこと (参照しているファイルを移すことではない)。
規則の SSOT はプラグインの規則の文書 (ファイル doc-structured/rules/doc-structured-domains.md)。
"""

from pathlib import PurePosixPath

from .domains import Project
from .problems import Problem


def check_direction(project: Project) -> list[Problem]:
    problems: list[Problem] = []
    for domain in project.domains:
        for entry in domain.entries():
            if entry.refers_to is None or entry.refers_to not in project.entries:
                continue  # 参照先が無いことは検査 h が報告する
            target = project.entries[entry.refers_to]
            source_dir = PurePosixPath(entry.path).parent
            target_dir = PurePosixPath(target.path).parent
            if target_dir != source_dir and target_dir in source_dir.parents:
                problems.append(
                    Problem(
                        "i",
                        entry.path,
                        f"refers_to の参照先 {target.id} は、祖先のディレクトリの {target.path} にある。"
                        f"参照される定義 ({target.id}) を、参照するファイルと同じディレクトリかその下に移す",
                        entry.refers_to_line,
                        entry.refers_to_column,
                    )
                )
    return problems
"""サブコマンド check が実行する検査と、検査 a (生成し直して差分が無い)。

検査の群 (決定の一覧の問 12 (3)):
  軽い群 (--light。デフォルト)  文書と YAML だけで実行できる検査。この版では a・b・h・i・k
  重い群 (--heavy)              データベースなどが要る検査。この版には無い
--all は両方、--only <検査> は 1 つだけを実行する。
検査 h (YAML の形式) に誤りがあると、定義の一覧と完全な名前が正しく作れないので、検査 a・b・i は実行せず、そのことを報告する。
検査 k (手書きの Markdown の行数) は YAML を使わないので、いつも実行する。
"""

import difflib
from dataclasses import dataclass, field
from pathlib import Path

from . import generated_header
from .direction import check_direction
from .documents import load_documents
from .domains import Project, load_project
from .generate import GITATTRIBUTES_PATH, HANDWRITTEN_MESSAGE, generated_files, handwritten_fix, is_handwritten, render_project
from .length import check_length
from .links import check_links
from .problems import Problem

LIGHT = ("a", "b", "h", "i", "k")
HEAVY: tuple[str, ...] = ()
ALL = LIGHT + HEAVY


@dataclass
class CheckResult:
    checks: tuple[str, ...]  # 実行するよう指定された検査
    problems: list[Problem] = field(default_factory=list)
    skipped: list[str] = field(default_factory=list)  # 検査 h の誤りのため実行しなかった検査

    @property
    def ok(self) -> bool:
        return not self.problems and not self.skipped


def check_generated(root: Path, project: Project) -> list[Problem]:
    """検査 a: 生成し直した内容と、今のファイルを比べる。"""
    problems: list[Problem] = []
    outputs = render_project(project)
    for relative, expected in outputs.items():
        header = generated_header.read_header(expected)
        if relative == GITATTRIBUTES_PATH:
            how = f"このファイルを直接編集せず、{header.command} を実行する。{generated_header.GITATTRIBUTES_GUIDE}"
        else:
            how = f"このファイルを直接編集せず、生成元 {header.source} の YAML を直して {header.command} を実行する"
        path = root / relative
        if not path.is_file():
            problems.append(Problem("a", relative, f"生成するはずのファイルが無い。{header.command} を実行する"))
            continue
        content = generated_header.read_file(path)
        if is_handwritten(content):
            problems.append(Problem("a", relative, f"{HANDWRITTEN_MESSAGE}。{handwritten_fix(relative)}"))
            continue
        if content.matches(expected):
            continue
        if content.header is None:
            # 先頭の記述が無く、手で書いたファイルでもない (空白と BOM だけの) ファイル。YAML の修正は要らない
            problems.append(Problem("a", relative, f"生成したファイルの中身が無い。{header.command} を実行する"))
            continue
        actual = content.text
        if actual == expected:
            # 読んだ内容は同じで、BOM か UTF-8 として読めないバイトだけが違う。YAML の修正は要らない
            problems.append(
                Problem(
                    "a", relative,
                    f"生成し直した内容と違う (BOM か、UTF-8 として読めないバイトがある)。{header.command} を実行する",
                )
            )
            continue
        diff = "".join(
            difflib.unified_diff(
                actual.splitlines(keepends=True),
                expected.splitlines(keepends=True),
                fromfile=f"{relative} (今のファイル)",
                tofile=f"{relative} (生成し直した内容)",
            )
        )
        problems.append(Problem("a", relative, f"生成し直した内容と違う。{how}", detail=diff))
    for relative, header in generated_files(root).items():
        if relative in outputs:
            continue
        if header.source and not (root / header.source).exists():
            message = f"生成元 {header.source} が無い。このファイルを消すか、生成元を戻す"
        else:
            command = header.command or generated_header.GENERATE_COMMAND
            message = f"生成し直すと消えるファイルが残っている。{command} を実行して消す"
        problems.append(Problem("a", relative, message))
    return problems


def run_checks(root: Path, checks: tuple[str, ...]) -> CheckResult:
    result = CheckResult(checks=checks)
    if not checks:
        return result
    project, yaml_problems = load_project(root)
    if "h" in checks:
        result.problems += yaml_problems
    if "b" in checks or "k" in checks:
        # ドメインの一覧はディレクトリ名から作るので、YAML に誤りがあっても手書きの Markdown を見つけられる
        index, document_problems = load_documents(root, project)
    if "k" in checks:
        result.problems += check_length(index)
    if yaml_problems:
        result.skipped = [c for c in checks if c in ("a", "b", "i")]
        return result
    if "b" in checks:
        result.problems += document_problems + check_links(index)
    if "i" in checks:
        result.problems += check_direction(project)
    if "a" in checks:
        result.problems += check_generated(root, project)
    return result
"""コマンド doc-structured の入口。

  doc-structured --version         ツールのバージョンを表示する (設定ファイルは読まない)
  doc-structured version           ツールのバージョンを表示する
  doc-structured generate          ドメインの YAML から、人が読む Markdown を生成する
  doc-structured check [--light|--heavy|--all|--only <検査>]
                                   検査を実行する。指定が無ければ軽い群 (--light)
  doc-structured links-fix [<ファイル>...] [--choose <ファイル> <ラベル> <ID か URL>]...
                                   手書きの Markdown の定義の行とファイルのアンカーを直す。判断の要るものが残れば終了コード 1
  doc-structured <知らない名前>     使い方を標準エラー出力に書き、終了コード 2 で終了する

サブコマンドは、起動時に設定ファイルを読み、形が違えばエラーの文を標準エラー出力に書いて終了コード 1 で終了する。
サブコマンドは sub-issue ごとに足す。
"""

import argparse
import sys
from pathlib import Path

from . import __version__
from . import check
from .config import Config, ConfigError, find_config, load_config
from .documents import load_documents
from .domains import load_project
from .generate import HANDWRITTEN_MESSAGE, HandwrittenFilesError, handwritten_fix, render_project, write_outputs
from .links_fix import Choice, ChoiceError, fix_files

VERSION_TEXT = f"doc-structured {__version__}"


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="doc-structured",
        description="アプリケーションの文書の構成の、生成と検査のツール",
    )
    parser.add_argument("--version", action="version", version=VERSION_TEXT)
    subparsers = parser.add_subparsers(dest="command", metavar="<サブコマンド>", required=True)
    subparsers.add_parser("version", help="ツールのバージョンを表示する")
    subparsers.add_parser("generate", help="ドメインの YAML から、人が読む Markdown を生成する")
    check_parser = subparsers.add_parser("check", help="検査を実行する。指定が無ければ軽い群 (--light)")
    group = check_parser.add_mutually_exclusive_group()
    group.add_argument("--light", action="store_true", help=f"軽い群の検査 ({'・'.join(check.LIGHT)}) を実行する")
    group.add_argument("--heavy", action="store_true", help="重い群の検査を実行する")
    group.add_argument("--all", action="store_true", help="すべての検査を実行する")
    group.add_argument("--only", metavar="<検査>", help="1 つの検査だけを実行する (例 --only a)")
    fix_parser = subparsers.add_parser(
        "links-fix",
        help="手書きの Markdown の定義の行とファイルのアンカーを直す。判断の要るものが残れば終了コード 1",
    )
    fix_parser.add_argument(
        "paths", nargs="*", metavar="<ファイル>", help="直す手書きの Markdown。指定が無ければ、すべての手書きの Markdown"
    )
    fix_parser.add_argument(
        "--choose", nargs=3, action="append", default=[], metavar=("<ファイル>", "<ラベル>", "<ID か URL>"),
        help="ファイルのラベルの参照先を、参照先の ID か外部の URL で指定する (何度でも指定できる)",
    )
    return parser


def run_check(config: Config, args: argparse.Namespace) -> int:
    if args.only is not None:
        if args.only not in check.ALL:
            print(
                f"doc-structured: このバージョンのツールに検査 {args.only} は無い (ある検査: {'・'.join(check.ALL)})",
                file=sys.stderr,
            )
            return 2
        checks: tuple[str, ...] = (args.only,)
    elif args.heavy:
        checks = check.HEAVY
    elif args.all:
        checks = check.ALL
    else:
        checks = check.LIGHT
    if not checks:
        print("重い群の検査は、このバージョンのツールには無い")
        return 0
    result = check.run_checks(config.root, checks)
    for problem in result.problems:
        print(problem.format())
    names = "・".join(checks)
    if result.skipped:
        print(f"YAML に誤りがあるので、検査 {'・'.join(result.skipped)} を実行しなかった (誤りは検査 h で確認する)")
    if result.ok:
        print(f"検査 {names}: 問題は無かった")
        return 0
    if result.problems:
        print(f"検査 {names}: 問題が {len(result.problems)} 件あった")
    else:
        print(f"検査 {names}: 実行できなかった検査がある")
    return 1


def run_generate(config: Config) -> int:
    project, problems = load_project(config.root)
    if problems:
        for problem in problems:
            print(problem.format(), file=sys.stderr)
        print(f"doc-structured: YAML に {len(problems)} 件の誤りがあるので、何も生成しなかった", file=sys.stderr)
        return 1
    try:
        written, deleted = write_outputs(config.root, render_project(project))
    except HandwrittenFilesError as e:
        for relative in e.paths:
            print(f"{relative}: {HANDWRITTEN_MESSAGE}。{handwritten_fix(relative)}", file=sys.stderr)
        print(
            f"doc-structured: 生成するファイルの場所に手で書いたファイルが {len(e.paths)} 件あるので、何も生成しなかった",
            file=sys.stderr,
        )
        return 1
    for path in written:
        print(f"書いた: {path}")
    for path in deleted:
        print(f"消した: {path}")
    if not written and not deleted:
        print("生成したファイルは、すべて最新だった")
    return 0


def _relative(config: Config, path: str) -> str | None:
    """コマンドに渡したパス (今のディレクトリからの相対か絶対) を、リポジトリのルートからの相対パスにする。"""
    resolved = (Path.cwd() / path).resolve()
    try:
        return resolved.relative_to(config.root.resolve()).as_posix()
    except ValueError:
        return None


def run_links_fix(config: Config, args: argparse.Namespace) -> int:
    project, problems = load_project(config.root)
    if problems:
        for problem in problems:
            print(problem.format(), file=sys.stderr)
        print(f"doc-structured: YAML に {len(problems)} 件の誤りがあるので、何も直さなかった", file=sys.stderr)
        return 1
    index, _ = load_documents(config.root, project)
    paths: list[str] | None = None
    if args.paths:
        paths = []
        for given in args.paths:
            relative = _relative(config, given)
            if relative is None or index.file(relative) is None:
                print(
                    f"doc-structured: {given} は、ドメインのディレクトリの下の手書きの Markdown でない", file=sys.stderr
                )
                return 1
            paths.append(relative)
    choices: list[Choice] = []
    for given, label, value in args.choose:
        relative = _relative(config, given)
        if relative is None:
            print(f"doc-structured: --choose のファイル {given} は、リポジトリの外にある", file=sys.stderr)
            return 1
        choices.append(Choice(relative, label, value))
    try:
        result = fix_files(config.root, index, paths, choices)
    except ChoiceError as e:
        print(f"doc-structured: {e}", file=sys.stderr)
        return 1
    for path in result.changed:
        print(f"書き換えた: {path}")
    for report in result.reports:
        print(report.format())
    if result.reports:
        print(f"判断の要るものが {len(result.reports)} 件ある (参照先を --choose で渡して、もう一度実行する)")
        return 1
    if not result.changed:
        print("直すものは無かった")
    return 0


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    try:
        config = load_config(find_config(Path.cwd()))
    except ConfigError as e:
        print(f"doc-structured: {e}", file=sys.stderr)
        return 1

    if args.command == "version":
        print(VERSION_TEXT)
        return 0
    if args.command == "generate":
        return run_generate(config)
    if args.command == "check":
        return run_check(config, args)
    if args.command == "links-fix":
        return run_links_fix(config, args)
    # argparse が知らないサブコマンドを拒否するので、ここには来ない
    raise AssertionError(f"知らないサブコマンド: {args.command} (設定: {config.path})")
"""検査が報告する問題。

出力の形は「<リポジトリのルートからのパス>:<行>:<列>: 検査 <記号>: <メッセージ>」。行と列は 1 から数える。
位置が無い問題 (ディレクトリやファイル全体の問題) は「<パス>: 検査 <記号>: <メッセージ>」。
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class Problem:
    check: str  # 検査の記号 (a・b・h・i など)
    path: str  # リポジトリのルートからの相対パス
    message: str
    line: int | None = None  # 1 から数える
    column: int | None = None  # 1 から数える
    detail: str = ""  # メッセージの後に続ける複数行 (差分など)

    def format(self) -> str:
        where = self.path
        if self.line is not None:
            where += f":{self.line}"
            if self.column is not None:
                where += f":{self.column}"
        text = f"{where}: 検査 {self.check}: {self.message}"
        if self.detail:
            text += "\n" + self.detail.rstrip("\n")
        return text

"""手書きの Markdown と、リンクの参照先の一覧。

ドメインのディレクトリの下の手書きの Markdown を見つけ、すべての Markdown (生成したファイルを含む) のアンカーから、
リンクの参照先の一覧を作る。形式の SSOT はプラグインの規則の文書 (ファイル doc-structured/rules/doc-structured-docs.md と
doc-structured/rules/doc-structured-domains.md)。要点:
  - 手書きのファイルは、ドメインのディレクトリの直下の concept.md・problem.md・design.md と、
    その種類と同じ名前のサブディレクトリの <名前>.md (子のファイル。1 階層だけ)
  - ほかの名前・場所の .md は、検査 b のエラーにする
  - 参照先のアンカーは、今のファイルの内容から読む (生成したファイルが古いことは検査 a が報告する)。YAML から決まる参照先
    (ドメイン・定義・生成したファイル) のファイルは、生成する側の対応で決め、そのファイルにアンカーがあるときだけ参照先にする
  - 参照先のラベルの候補は、ID・名前・限定付きの名前 (「種類 + 名前」に、親を直近から 0 個以上足した形)
"""

import posixpath
from dataclasses import dataclass, field
from pathlib import Path

from . import generated_header, markdown, names
from .domains import DOMAINS_DIR, Domain, Project, rel
from .generate import entry_file, file_path
from .names import Part
from .problems import Problem

README = "README.md"
# ドメインのディレクトリの直下の、生成するファイルの名前
GENERATED_NAMES = {README, *names.FILE_KINDS.values()}


@dataclass
class HandwrittenFile:
    """ドメインのディレクトリの下の、手書きのファイル。"""

    path: str  # リポジトリのルートからの相対パス
    domain: Domain
    symbol: str  # 手書きのファイルの種類の記号 (concept・problem・design)
    child: str | None  # 子のファイルなら、その名前
    document: markdown.Document

    @property
    def id(self) -> str:
        parts = [Part("d", self.domain.name), Part(self.symbol, None)]
        if self.child is not None:
            parts.append(Part(names.CHILD_FILE_SYMBOL, self.child))
        return names.build_id(parts)

    @property
    def display(self) -> str:
        """限定付きの名前に書くファイル名。子のファイルは、ドメインのディレクトリからのパス。"""
        if self.child is None:
            return names.HANDWRITTEN_FILE_KINDS[self.symbol]
        return f"{self.symbol}/{self.child}.md"

    def parts(self) -> list[str]:
        symbol = names.CHILD_FILE_SYMBOL if self.child is not None else self.symbol
        return [self.domain.full_name(), names.format_part(symbol, self.display)]

    def full_name(self) -> str:
        return names.join_parts(self.parts())


@dataclass
class Target:
    """リンクの参照先 (アンカーのある定義・ファイル・節)。"""

    id: str
    path: str  # アンカーを書いたファイルの、リポジトリのルートからの相対パス
    parts: list[str]  # ドメインから自分までの「種類 + 名前」
    name: str | None  # ラベルの候補にする名前 (日本語名・見出しの文・コードの書式のファイル名)

    def full_name(self) -> str:
        return names.join_parts(self.parts)

    def qualified_names(self) -> list[str]:
        """限定付きの名前。自分だけの「種類 + 名前」から、すべての親を書いた完全な名前まで。"""
        return [names.join_parts(self.parts[i:]) for i in range(len(self.parts) - 1, -1, -1)]

    def labels(self) -> set[str]:
        """ラベルの候補を、比べる形 (markdown.normalize_label) にしたもの。"""
        found = {self.id, *self.qualified_names()}
        if self.name:
            found.add(self.name)
        return {markdown.normalize_label(label) for label in found}

    def href(self, from_path: str) -> str:
        """from_path のファイルに書く、定義の行の href。"""
        if self.path == from_path:
            return f"#{self.id}"
        return f"{posixpath.relpath(self.path, posixpath.dirname(from_path))}#{self.id}"


@dataclass
class Index:
    files: list[HandwrittenFile] = field(default_factory=list)
    targets: dict[str, Target] = field(default_factory=dict)
    # すべての Markdown のアンカー。ID から、それを書いたファイルとアンカーへの対応 (同じ ID が 2 つあれば 2 つ)
    anchors: dict[str, list[tuple[str, markdown.Anchor]]] = field(default_factory=dict)
    documents: dict[str, markdown.Document] = field(default_factory=dict)  # パスから、読んだ Markdown への対応

    # 比べる形のラベルから、その候補の参照先への対応。最初の candidates の呼び出しで、参照先の一覧から 1 度だけ作る
    _by_label: dict[str, list[Target]] | None = field(default=None, repr=False)

    def candidates(self, label: str) -> list[Target]:
        if self._by_label is None:
            self._by_label = {}
            for target in sorted(self.targets.values(), key=lambda t: t.id):
                for key in target.labels():
                    self._by_label.setdefault(key, []).append(target)
        return list(self._by_label.get(markdown.normalize_label(label), []))

    def file(self, path: str) -> HandwrittenFile | None:
        for handwritten in self.files:
            if handwritten.path == path:
                return handwritten
        return None


def section_name(file_id: str, anchor: str) -> str | None:
    """節のアンカーの名前。file_id のファイルの節のアンカーの形 (<ファイルの ID>-h-<名前>) でなければ None。"""
    prefix = f"{file_id}-{names.SECTION.symbol}-"
    if not anchor.startswith(prefix):
        return None
    name = anchor[len(prefix) :]
    return name if names.is_name(name) else None


def read_markdown(path: Path) -> markdown.Document:
    return markdown.parse(generated_header.read_file(path).text)


class _Finder:
    def __init__(self, root: Path, project: Project):
        self.root = root
        self.project = project
        self.index = Index()
        self.problems: list[Problem] = []

    def problem(self, path: str, message: str, line: int | None = None, column: int | None = None) -> None:
        self.problems.append(Problem("b", path, message, line, column))

    def find(self) -> None:
        for domain in self.project.domains:
            self.find_in_domain(domain)
        self.read_anchors()
        self.add_targets()

